+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter understood by {@link CustomerRepository}.
+ *
+ * @param name     whitespace separated terms; each must occur in the first or last name
+ * @param statuses accepted statuses; empty means any
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    public boolean isEmpty() {
+        return name.isBlank() && statuses.isEmpty();
+    }
+
+    public boolean matches(Customer c) {
+        if (!statuses.isEmpty() && !statuses.contains(c.status())) {
+            return false;
+        }
+        String normalized = fold(name).trim();
+        if (normalized.isEmpty()) {
+            return true;
+        }
+        String first = fold(c.firstName());
+        String last = fold(c.lastName());
+        for (String term : normalized.split("\\s+")) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /** Lower-cases and strips accents. */
+    static String fold(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
